/**
 * Approve / reject modal for pending course requests.
 *
 * @module local_sentientia_request/decide
 *
 * Build note (2026-06-11, WF-019): hand-rolled from amd/src/decide.js to
 * classic AMD because no grunt build is checked in (tree-wide CRLF eslint
 * noise blocks `grunt amd` — same practice as my_requests.min.js). Keep in
 * sync with the src on every change. The dual-target modal factory
 * (5.2 core/modal vs 5.1 core/modal_factory) uses the global require()
 * exactly like the src.
 */
define("local_sentientia_request/decide",
    ["core/ajax", "core/notification", "core/modal_events"],
    function(Ajax, Notification, ModalEvents) {

    var createSaveCancelModal = function(spec) {
        return new Promise(function(resolve, reject) {
            // WF-024: 5.2 SAVE_CANCEL modal is core/modal_save_cancel. The old
            // core/modal Modal.create({modalType:"SAVE_CANCEL"}) built a base
            // modal with an EMPTY footer (no Save/Cancel) — decision unsubmittable.
            var viaFactory = function() {
                require(["core/modal_factory"], function(ModalFactory) {
                    ModalFactory.create({type: ModalFactory.types.SAVE_CANCEL, title: spec.title, body: spec.body})
                        .then(resolve).catch(reject);
                }, reject);
            };
            require(["core/modal_save_cancel"], function(ModalSaveCancel) {
                if (ModalSaveCancel && typeof ModalSaveCancel.create === "function") {
                    ModalSaveCancel.create({title: spec.title, body: spec.body})
                        .then(resolve).catch(reject);
                    return;
                }
                viaFactory();
            }, viaFactory);
        });
    };

    // Escape dataset-sourced strings before HTML interpolation (WF-019 hardening).
    var esc = function(s) {
        return String(s).replace(/[&<>"']/g, function(c) {
            return {"&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;", "'": "&#39;"}[c];
        });
    };

    var init = function() {
        document.addEventListener("click", async function(e) {
            var btn = e.target.closest('[data-action="decide-request"]');
            if (!btn) {
                return;
            }
            e.preventDefault();
            var requestid = parseInt(btn.dataset.requestid, 10);
            var decision = btn.dataset.decision; // 'approved' | 'rejected'
            var requester = esc(btn.dataset.requester || "this user");
            var course = esc(btn.dataset.course || "this course");
            if (!requestid || ["approved", "rejected"].indexOf(decision) === -1) {
                return;
            }

            var isApprove = decision === "approved";
            var title = (isApprove ? "Approve request from " : "Reject request from ") + requester;
            var body = "<p>" + (isApprove ? "Approving" : "Rejecting") +
                " the request for <strong>" + course + "</strong>.</p>" +
                "<div class=\"mb-2\">" +
                "<label class=\"form-label\">" + (isApprove ? "Note (optional)" : "Reason (required)") + "</label>" +
                "<textarea id=\"decision_note\" class=\"form-control\" rows=\"3\" placeholder=\"" +
                (isApprove ? "e.g. relevant to your role" : "Tell the requester why") +
                "\"></textarea></div>";

            var modal = await createSaveCancelModal({title: title, body: body});

            modal.getRoot().on(ModalEvents.save, function() {
                var note = document.getElementById("decision_note").value || "";
                if (!isApprove && note.trim() === "") {
                    Notification.alert("Reason required", "Please give the requester a reason for rejection.");
                    return;
                }
                Ajax.call([{
                    methodname: "local_sentientia_request_decide",
                    args: {requestid: requestid, decision: decision, note: note}
                }])[0].then(function() {
                    window.location.reload();
                    return;
                }).catch(Notification.exception);
            });

            modal.show();
        });
    };

    return {init: init};
});
